import Foundation

enum MovementLibrary {
    private static func movement(_ id: String, _ name: String, _ pattern: Pattern, _ equipment: Set<Equipment>, _ cue: String, _ video: String, advanced: Bool = false, source: String? = nil, about: String) -> Movement {
        Movement(id: id, name: name, pattern: pattern, equipment: equipment, advanced: advanced, cue: cue, videoID: video, source: source ?? "https://www.youtube.com/watch?v=\(video)", about: about)
    }

    // Direct demonstrations; provenance and review notes are in VIDEO_SOURCES.md.
    static let all: [Movement] = [
        movement("air-squat", "Air squats", .squat, [], "Keep your feet planted and your knees tracking with your toes. Move through a comfortable depth.", "rMvwVtlqjTE", about: "A bodyweight squat for the legs and hips. Sit your hips back and down with your chest up and heels planted, then stand all the way up."),
        movement("walking-lunge", "Walking lunges", .squat, [], "Alternate legs and stay tall. Give yourself enough room for each step.", "DlhojghkaQ0", about: "Step forward and lower until both knees bend to about 90 degrees, then step through into the next rep. Keep your torso upright and your front knee over your foot."),
        movement("front-squat", "Barbell front squats", .squat, [.barbell, .rack], "Keep your elbows lifted. Choose a light load you can control for the whole interval.", "uYumuL_G_V0", about: "A squat with the barbell resting on the front of your shoulders. Keep your elbows high and torso upright as you squat down, then drive up through your whole foot."),
        movement("back-squat", "Barbell back squats", .squat, [.barbell, .rack], "Set your cage safeties before starting. Use a manageable load and controlled reps.", "QmZAiBqPvZw", about: "A squat with the barbell across your upper back. Brace your core, sit your hips back and down with knees tracking your toes, and stand up through your whole foot."),
        movement("dumbbell-front-squat", "Dumbbell front squats", .squat, [.dumbbells], "Rest the dumbbells at your shoulders and keep your chest lifted.", "B86Zj72LwzA", about: "A squat holding dumbbells at your shoulders. Keep your elbows up and torso tall as you squat down, then stand through your heels."),
        movement("wall-sit", "Wall sit", .squat, [.wall], "Keep your back against the wall. Hold a comfortable depth and keep breathing.", "6Li55TURhVg", source: "https://www.youtube.com/watch?v=6Li55TURhVg", about: "An isometric leg hold with your back flat against a wall. Slide down until your thighs are near parallel with your knees over your ankles, and hold."),
        movement("deadlift", "Barbell deadlifts", .hinge, [.barbell], "Keep the bar close and your back steady. Reset between reps; use a repeatable load.", "1ZXobu7JvvE", about: "Lifting a barbell from the floor to standing using your legs and hips. Keep a flat back and the bar against your legs, and finish standing tall with hips and knees locked out."),
        movement("dumbbell-deadlift", "Dumbbell deadlifts", .hinge, [.dumbbells], "Send your hips back and keep the dumbbells close to your legs.", "JNpUNRPQkAk", about: "A hip hinge that lifts dumbbells from the floor to standing. Keep a flat back and soft knees, push your hips back on the way down, and squeeze your glutes to stand."),
        movement("glute-bridge", "Glute bridges", .hinge, [], "Press through your feet and lift your hips without arching your lower back.", "xp5TE9DtWXA", source: "https://www.youtube.com/watch?v=xp5TE9DtWXA", about: "A floor exercise on your back that strengthens the glutes and hamstrings. With knees bent and feet flat, drive your hips up until shoulders, hips, and knees line up, then lower slowly."),
        movement("kettlebell-swing", "Kettlebell swings", .hinge, [.kettlebell], "Drive with your hips. Choose a light bell and a range you can control.", "mKDIuUbH94Q", about: "A hip-powered swing of the kettlebell from between your legs to about chest height. Hinge rather than squat, keep a flat back, and snap your hips forward so your arms just guide the bell."),
        movement("power-clean", "Barbell power cleans", .hinge, [.barbell], "Start light and stay patient off the floor. Reset between reps.", "KwYJTpQ_x5A", about: "An explosive pull of the barbell from the floor to the front of your shoulders. Keep the bar close, extend your hips hard, then pull under and catch it in a partial squat with elbows high."),
        movement("dumbbell-power-clean", "Dumbbell power cleans", .hinge, [.dumbbells], "Use dumbbells you can move fast. Land softly and stand tall each rep.", "viWI2rEt-HU", about: "An explosive lift of two dumbbells from the floor to your shoulders. Hinge with a flat back, drive your hips through, and catch the dumbbells at your shoulders in a quarter squat."),
        movement("dumbbell-power-snatch", "Dumbbell power snatches", .hinge, [.dumbbells], "Alternate arms as needed. Keep the dumbbell close as it travels up.", "3mlhF3dptAo", about: "One dumbbell taken from the floor to overhead in a single fast motion. Drive with your hips, keep the dumbbell close to your body, and finish with a locked arm directly over your shoulder."),
        movement("push-up", "Push-ups", .push, [], "Keep your body in one line. Scale to your knees when needed to maintain control.", "0pkjOk0EiAk", about: "A bodyweight press from the floor for the chest, shoulders, and triceps. With hands under your shoulders and a tight core, lower your chest to the floor and press back to straight arms."),
        movement("push-press", "Barbell push presses", .push, [.barbell], "Dip straight down, then drive through your legs. Finish with the bar balanced overhead.", "iaBVSJm78ko", about: "A barbell overhead press helped by a quick dip and drive of the legs. Dip a few inches with your torso vertical, drive up, and press to locked arms with the bar over your midfoot."),
        movement("shoulder-press", "Barbell shoulder presses", .push, [.barbell], "Squeeze your glutes and keep your ribs down. Use a load you can press without leaning back.", "5yWaNOvgFCM", about: "A strict press of the barbell from your shoulders to overhead, with no leg drive. Keep your core braced, move your head back to clear the bar, and lock out with the bar over your midfoot."),
        movement("dumbbell-push-press", "Dumbbell push presses", .push, [.dumbbells], "Use a short leg drive and keep your ribs from flaring as you press.", "4tCaD42ghlc", about: "An overhead dumbbell press helped by a short dip and drive of the legs. Keep your torso upright on the dip and finish with locked arms and biceps by your ears."),
        movement("dumbbell-thruster", "Dumbbell thrusters", .push, [.dumbbells], "Move smoothly from the squat into the press. Use light dumbbells for repeatable reps.", "u3wKkZjE8QM", about: "A front squat that flows straight into an overhead press. Squat with the dumbbells at your shoulders, then use the drive out of the bottom to press them to full lockout."),
        movement("wall-walk", "Wall walks", .push, [.wall], "Walk only as close to the wall as you can control, then reverse slowly. Take breaks within the interval.", "NK_OcHEm8yM", advanced: true, about: "From a push-up position with your feet at the wall, walk your feet up the wall and your hands back toward it, then return. Keep your core tight and your body in a straight line."),
        movement("wall-handstand", "Wall handstand hold", .push, [.wall], "Use the wall for support and keep pushing through your shoulders. Come down before control fades.", "KNC5lkoE2Fs", advanced: true, source: "https://www.youtube.com/watch?v=KNC5lkoE2Fs", about: "An upside-down hold with your feet against the wall. Stack wrists, shoulders, and hips, lock your arms, and push the floor away with your core tight."),
        movement("strict-handstand-push-up", "Handstand push-ups", .push, [.wall], "Use strict, controlled reps with wall support. Stop before your arms give out; rest as needed.", "0wDEO6shVjc", advanced: true, about: "A push-up upside down against the wall, without kicking. Lower your head under control to form a triangle with your hands, then press back to locked arms."),
        movement("strict-pull-up", "Strict pull-ups", .pull, [.pullUpBar], "Start from a controlled hang. Pull without swinging and lower with control.", "HRV5YKKaeVw", about: "Pulling from a dead hang until your chin clears the bar, without kipping. Pull your elbows down toward your ribs and lower all the way to straight arms."),
        movement("band-row", "Resistance band rows", .pull, [.bands], "Stand securely on the band, hinge at your hips, and pull your elbows back without rounding your back.", "Y3H17rshgZE", source: "https://www.youtube.com/watch?v=Y3H17rshgZE", about: "A resistance-band pull for the upper back. From a hinged, flat-back position, pull the handles toward your lower ribs and squeeze your shoulder blades together."),
        movement("burpee", "Burpees", .conditioning, [], "Find a steady pace. Step back and forward to reduce impact when needed.", "auBLPXO8Fww", about: "A full-body movement: drop your chest to the floor, then stand and jump with your hands overhead. Keep your core tight on the way down and land softly."),
        movement("box-jump", "Box jumps", .conditioning, [.box], "Land with both feet securely on the box. Stand tall and step down with control.", "NBY9-kTuHEk", about: "A two-footed jump onto a box. Swing your arms, land softly with both feet fully on the box, and stand all the way up at the top."),
        movement("box-step-up", "Box step-ups", .conditioning, [.box], "Plant your whole foot on the box and alternate your leading leg.", "5qjqDHOUh-A", about: "Stepping up onto a box one leg at a time. Drive through the heel of your top foot to stand fully on the box, then step down with control."),
        movement("single-under", "Jump rope singles", .conditioning, [.jumpRope], "Keep jumps small and turn the rope from your wrists.", "hCuXYrTOMxI", about: "Basic jump rope with one rope pass per jump. Stay on the balls of your feet, keep your elbows close to your sides, and turn the rope with your wrists."),
        movement("abmat-sit-up", "Sit-ups", .core, [], "Use a folded towel or mat behind your lower back if you have one.", "VIZX2Ru9qU8", about: "Lying back with the soles of your feet together, sit up until your shoulders pass your hips, then roll back down. Reach your hands to the floor overhead and then to your feet each rep."),
        movement("hollow-rock", "Hollow rocks", .core, [], "Bend your knees or bring your arms in to make it easier. Keep your lower back on the floor.", "SfkuOb_1GK8", about: "A rocking hold on your back with arms and legs extended off the floor. Press your lower back into the floor, keep your body in a banana shape, and rock without bending at the hips."),
        movement("v-up", "V-ups", .core, [], "Bend your knees to make it easier. Move with control rather than speed.", "7UVgs18Y1P4", about: "From lying flat, lift your legs and torso together to touch your toes above your hips, then lower back down. Keep your legs straight and reach through your hands."),
        movement("hanging-knee-raise", "Hanging knee raises", .core, [.pullUpBar], "Keep the swing small. Drop down and reset when your grip fades.", "lW4onyuCkzA", source: "https://www.youtube.com/watch?v=lW4onyuCkzA", about: "Hanging from the bar, raise your knees toward your chest and lower them with control. Keep your shoulders engaged and avoid swinging."),
        movement("plank", "Plank", .core, [], "Drop to your knees when your hips start to sag.", "mwlp75MS6Rg", source: "https://www.youtube.com/watch?v=mwlp75MS6Rg", about: "A static hold on your forearms and toes. Keep a straight line from head to heels, squeeze your glutes, and do not let your hips sag or pike.")
    ]
}
